WITHIN_HOURS_OVERTIME.conversion:
// 労働基準法 arts.32, 37: ctx.work.days is the clock-proven roster. Hours past 8 a day or 40 a week are statutory overtime; other overtime stays within the legal hours.
const hourly = ctx.hour_rate;
const employer = get(ctx.subject.employer, 'entity_extension_data', {});
const limit = get(employer, 'weekly_limit_44', false) === true ? ctx.lookup.special_establishment_weekly_hours : ctx.lookup.standard_weekly_hours;
const opening = Number(get(employer, 'week_start', 0));
const days = get(ctx, 'work.days', []).filter((day) => get(day, 'day_type', 'WORK') !== 'REST').toSorted((a, b) => (a.date < b.date ? -1 : 1));
let week = '';
let used = 0;
let statutory = 0;
let within = 0;
for (const day of days) {
	const start = add_days(day.date, 0 - ((weekday(day.date) - opening + 7) % 7));
	if (start !== week) {
		week = start;
		used = 0;
	}
	const worked = Number(get(day, 'worked_hours', 0));
	const ordinary = Math.min(worked, ctx.lookup.standard_daily_hours, Math.max(0, limit - used));
	used = used + ordinary;
	const extra = Number(get(day, 'overtime_hours', 0));
	const over = Math.min(extra, worked - ordinary);
	statutory = statutory + over;
	within = within + extra - over;
}
return within * hourly * ctx.lookup.multiplier;

