REST_DAY_WORK.conversion:
// 労働基準法 art.37(1), 割増賃金令: every clock-proven hour on the statutory rest day; art.13: the employer's own rest-day multiple stands where it pays more.
const hourly = ctx.hour_rate;
const hours = sum(get(ctx, 'work.days', []).filter((day) => get(day, 'day_type', 'WORK') === 'REST').map((day) => Number(get(day, 'worked_hours', 0))));
const multiple = Math.max(ctx.lookup.multiplier, Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0)));
return hours * hourly * multiple;

NIGHT_WORK.conversion:
// 労働基準法 art.37(4): the premium on clock-proven hours between 22:00 and 05:00.
const hourly = ctx.hour_rate;
const zone = get(ctx.subject.employer, 'time_zone', 'Asia/Tokyo');
const minutes = sum(get(ctx, 'work.days', []).map((day) => clock_window_minutes(get(day, 'intervals', []), zone, ctx.lookup.night_from, ctx.lookup.night_to)));
return (minutes / 60) * hourly * ctx.lookup.multiplier;

