COMMUTING_ALLOWANCE.conversion:
// 所得税法施行令 art.20の2: transit to 150,000 a month; a car or bicycle by one-way distance, plus a car park and any transit fare, within that 150,000.
const facts = ctx.subject.employment.employee_extension_data;
const amount = Number(get(ctx.subject.employment, 'terms.allowances.COMMUTING_ALLOWANCE.amount', 0));
const km = get(facts, 'commute_car_km_one_way', null);
const band = km == null ? null : ctx.lookup.car_distance_bands.find((row) => row.below == null || Number(km) < row.below);
const parking = band == null || band.amount === 0 ? 0 : Math.min(Number(get(facts, 'commute_parking_fee', 0)), ctx.lookup.parking_monthly_cap);
const car = band == null ? ctx.lookup.commuting_monthly_limit : band.amount + parking + Number(get(facts, 'commute_transit_fare', 0));
const limit = Math.min(car, ctx.lookup.commuting_monthly_limit);
return Math.min(amount, limit);

