HEALTH.eligibility:
// The monthly premium goes with the salary: an off-cycle run pays none, and the bonus rows carry what it pays.
if (get(ctx.run, 'kind', '') === 'OFF_CYCLE') return false;
const category = get(ctx.subject.employment.terms, 'statutory_work_category', 'NONE');
const facts = ctx.subject.employment.employee_extension_data;
// 高齢者医療確保法 arts.50, 52: cover ends on the 75th birthday itself, not its eve (the pension and care ages).
const age = age_on(get(ctx.subject.employment, 'payroll.date_of_birth', ''), ctx.run.salary_coverage.to);
if (!['SOCIAL_AND_EMPLOYMENT', 'SOCIAL_ONLY'].includes(category)) return false;
