if (!(age < ctx.lookup.health_maximum_age_years)) return false;
const end = get(ctx.subject.employment, 'effective_range.to', null);
// 健康保険法 art.156(3), 厚生年金保険法 art.19(1): cover is lost the day after the exit, and that month is not charged.
return end == null || end >= ctx.run.salary_coverage.to;

HEALTH.employee_amount:
const facts = ctx.subject.employment.employee_extension_data;
const region = get(facts, 'insured_office_region', get(ctx.subject.employer.entity_extension_data, 'region', ''));
const society = get(ctx.subject.employer.entity_extension_data, 'health_insurer', 'KYOKAI') === 'SOCIETY';
