const healthRate = society ? Number(get(ctx.subject.employer.entity_extension_data, 'society_health_rate_percent', 0)) : ctx.lookup.prefecture_rate_percent[region];
let careRate = 0;
if (nursing) careRate = society ? Number(get(ctx.subject.employer.entity_extension_data, 'society_care_rate_percent', 0)) : ctx.lookup.nursing_percent;
const rate = healthRate + careRate;
const elected = get(facts, 'statutory.HEALTH.standard_monthly_remuneration', null);
