INCOME_TAX.eligibility:
const residency = get(ctx.subject.employment.terms, 'residency_status', 'RESIDENT');
if (get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) === 0) return false;
if (get(ctx.subject.employment.employee_extension_data, 'statutory.INCOME_TAX.treaty_exempt', false) === true) return false;
return residency !== '';

INCOME_TAX.employee_amount:
const pick = (rows, value) => {
	for (const row of rows) if (row.up_to == null || value <= row.up_to) return row;
	return rows[rows.length - 1];
};
const facts = ctx.subject.employment.employee_extension_data;
const terms = ctx.subject.employment.terms;
const elections = get(facts, 'statutory.INCOME_TAX', {});
if (get(elections, 'treaty_exempt', false) === true) return 0;
// 所得税法 art.9(1)(v), 所得税基本通達 28-1: pay in NON_TAXABLE_PAY, above BASIC, is outside the base.
const month = get(ctx.balances, 'month', {});
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const heldIn = (paid, code) => (Object.hasOwn(month, paid + '.' + code) ? Number(month[paid + '.' + code]) : 0);
// 労働基準法 art.24(2): each wage month stands alone, so a whole-month salary already in this pay month is another wage month's or another employer's.
const coverage = ctx.run.salary_coverage;
const wholeMonth = String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn(paidMonth, 'BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(paidMonth, code));
// 所得税法 art.185(1)(i): the table reads the month's pay, so a later payment in the month reads it on the total and withholds the difference. Art.190 settles the year.
const exempt = get(ctx.subtotals, 'NON_TAXABLE_PAY', 0) - get(ctx.subtotals, 'PAID_BASIC', 0) + Math.max(0, before('NON_TAXABLE_PAY') - before('PAID_BASIC'));
const ordinary = get(ctx.subtotals, 'ORDINARY_WAGES', 0) + before('ORDINARY_WAGES');
const salary = ordinary - exempt;
const bonus = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) + before('ADDITIONAL_WAGES') - ordinary;
if (get(terms, 'residency_status', 'RESIDENT') === 'NON_RESIDENT') return round((salary + bonus) * ctx.lookup.nonresident_rate, 1, 'DOWN') - before('INCOME_TAX.employee');
const declared = get(elections, 'dependency_declaration_filed', false) === true;
const dependants = Number(get(elections, 'withholding_dependants', 0));
const social = (code) => get(ctx.statutory, code + '.employee', 0) + before(code + '.employee');
const salaryCodes = ['HEALTH', 'PENSION', 'EI', 'CHILD_SUPPORT'];
// 所得税法 art.74: the premiums the month's pay owes, so a recovery's overcharge stays out.
const kind = get(ctx.subject.employer.entity_extension_data, 'ei_industry_class', 'GENERAL');
// The employee share: 50 sen or less is dropped, above 50 sen rounds up (通貨の単位及び貨幣の発行等に関する法律 art.3).
const owedEi = round(ordinary * ctx.lookup.employee_rate[kind] - 0.0001, 1, 'HALF_UP');
const salarySocial = sum(['HEALTH', 'PENSION', 'CHILD_SUPPORT'].map(social)) + Math.min(social('EI'), owedEi);
const bonusSocial = sum(['HEALTH_BONUS', 'PENSION_BONUS', 'EI_BONUS', 'CHILD_SUPPORT_BONUS'].map(social));
// 甲欄 by the 電算機計算の特例 (平成24年財務省告示第116号).
const ko = (net) => {
	const deduction = pick(ctx.lookup.salary_income_deduction, net);
	const basic = pick(ctx.lookup.basic_deduction, net);
	const taxable = net - round(net * deduction.rate + deduction.offset, 1, 'UP') - (net * basic.rate + basic.offset) - ctx.lookup.dependant_monthly_deduction * dependants;
	if (taxable <= 0) return 0;
	const band = pick(ctx.lookup.monthly_tax, taxable);
	return round(taxable * band.rate + band.offset, ctx.lookup.ten_units, 'HALF_UP');
};
// 乙欄 and 丙欄: under the first row a share, then the table, then a fixed sum plus a rate on the excess.
const banded = (amount, table, excess) => {
	const top = excess.filter((row) => amount > row.from).at(-1);
	if (top != null) return round(top.base + (amount - top.from) * top.rate, 1, 'DOWN');
	return bracket(amount, table);
};
const otsu = (net) => {
	const amount = round(net, 1, 'DOWN');
	if (amount < ctx.lookup.otsu_small_salary_ceiling) return round(amount * ctx.lookup.otsu_small_salary_rate, 1, 'DOWN');
	const tax = banded(amount, ctx.lookup.otsu_monthly_tax, ctx.lookup.otsu_excess);
	return Math.max(0, tax - Number(get(elections, 'secondary_dependants', 0)) * ctx.lookup.otsu_dependant_deduction);
};
const table = (net) => {
	if (net <= 0) return 0;
	return declared ? ko(net) : otsu(net);
};
const salaryTax = () => {
	if (salary <= 0) return 0;
	if (get(facts, 'daily_wage_earner', false) !== true) return table(salary - salarySocial);
	// 所得税法 art.185(1)(iii): 日雇 pay is taxed day by day on the 丙欄.
	const worked = get(ctx, 'work.days', []).filter((day) => get(day, 'worked', false) === true).length;
	const rate = Number(get(terms, 'rate.amount', 0));
	const days = get(terms, 'rate.unit', '') === 'DAILY' && rate > 0 ? round(salary / rate, 1, 'UP') : Math.max(worked, 1);
	const perDay = round((salary - salarySocial) / days, 1, 'DOWN');
	if (perDay <= 0) return 0;
	return days * banded(perDay, ctx.lookup.hei_daily_tax, ctx.lookup.hei_excess);
};
// 所得税法 art.186: the bonus rate turns on the previous month's pay after premiums.
const lastMonth = add_months(paidMonth + '-01', -1).slice(0, 7);
const heldLast = (code) => heldIn(lastMonth, code);
const prior = heldLast('ORDINARY_WAGES') - Math.max(0, heldLast('NON_TAXABLE_PAY') - heldLast('PAID_BASIC')) - sum(salaryCodes.map((code) => heldLast(code + '.employee')));
const bonusTax = () => {
	const net = bonus - bonusSocial;
	if (net <= 0) return 0;
	if (prior > 0 && net <= prior * ctx.lookup.bonus_prior_pay_multiple) {
		const rows = declared ? ctx.lookup.bonus_rate_ko[Math.min(dependants, ctx.lookup.bonus_rate_ko.length - 1)] : ctx.lookup.bonus_rate_otsu;
		return round(net * bracket(round(prior, 1, 'DOWN'), rows), 1, 'DOWN');
	}
	// No prior pay, or over ten times it: the 月額表 on a sixth of the bonus, a twelfth for a period over six months.
	const long = get(ctx.subtotals, 'LONG_PERIOD_BONUS', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0) > 0;
	const months = long ? ctx.lookup.bonus_long_period_divisor : ctx.lookup.bonus_divisor;
	const base = Math.max(0, prior);
	return months * (table(round(net / months, 1, 'DOWN') + base) - table(base));
};
return round(salaryTax() + bonusTax(), 1, 'DOWN') - before('INCOME_TAX.employee');

YEAR_END_ADJUSTMENT.eligibility:
if (get(ctx.subject.employment.terms, 'residency_status', 'RESIDENT') !== 'RESIDENT') return false;
const facts = ctx.subject.employment.employee_extension_data;
if (get(facts, 'statutory.INCOME_TAX.dependency_declaration_filed', false) !== true) return false;
// 所得税法 art.190: the year's last pay falls in December. The balance turns over by pay date, so this reads the pay date too.
if (ctx.run.pay_date.substring(5, 7) === '12') return true;
// 年末調整のしかた: a leaver is adjusted at the exit on departure abroad, or with no further salary expected after a disability exit or on low pay.
const end = get(ctx.subject.employment, 'effective_range.to', null);
if (end == null) return false;
if (end < ctx.run.salary_coverage.from || end > ctx.run.salary_coverage.to) return false;
if (get(facts, 'departure_abroad', false) === true) return true;
if (get(facts, 'further_salary_expected_this_year', true) !== false) return false;
if (get(facts, 'severe_disability_prevents_reemployment', false) === true) return true;
const earned = (code) => get(ctx, 'balances.ytd.' + code, 0) + get(ctx.subtotals, code, 0);
return earned('ADDITIONAL_WAGES') - earned('NON_TAXABLE_PAY') + earned('BASIC') <= ctx.lookup.midyear_salary_limit;

YEAR_END_ADJUSTMENT.employee_amount:
const pick = (rows, value) => {
	for (const row of rows) if (row.up_to == null || value <= row.up_to) return row;
	return rows[rows.length - 1];
};
const elections = get(ctx.subject.employment.employee_extension_data, 'statutory.YEAR_END_ADJUSTMENT', {});
const held = get(ctx, 'balances.statutory_contribution', {});
const earned = (code) => get(ctx, 'balances.ytd.' + code, 0) + get(ctx.subtotals, code, 0);
const paid = (code) => (Object.hasOwn(held, code + '.employee') ? held[code + '.employee'] : 0) + get(ctx.statutory, code + '.employee', 0);
// 所得税法 art.9(1)(v): NON_TAXABLE_PAY, above BASIC, is not the year's pay.
const salary = earned('ADDITIONAL_WAGES') - earned('NON_TAXABLE_PAY') + earned('BASIC') + Number(get(elections, 'prior_employer_income', 0));
// 所得税法 art.190: pay above 20,000,000 is settled on the employee's own return.
if (salary <= 0 || salary > 20000000) return 0;
const band = pick(ctx.lookup.annual_salary_income_deduction, salary);
// 所得税法 別表第五: under 6,600,000 the graduated bands apply to the lower bound of the table's 4,000-yen row.
const stepped = band.rate > 0 && band.rate < 1 && salary < 6600000;
const row = stepped ? round(salary / 4, 1000, 'DOWN') * 4 : salary;
const income = Math.max(0, row - round(row * band.rate + band.offset, 1, 'UP') - Number(get(elections, 'yea_income_adjustment', 0)));
const basic = pick(ctx.lookup.annual_basic_deduction, income + Number(get(elections, 'yea_other_income', 0)));
// 所得税法 art.74: what was paid back was never borne, what was collected late was. Both sit alone above FINAL_PAY.
const social = sum(['HEALTH', 'HEALTH_BONUS', 'PENSION', 'PENSION_BONUS', 'EI', 'EI_BONUS', 'CHILD_SUPPORT', 'CHILD_SUPPORT_BONUS'].map(paid)) - (earned('SOCIAL_INSURANCE_REFUND') - earned('FINAL_PAY'));
const declared = sum(['prior_employer_social_insurance', 'yea_other_social_insurance', 'yea_insurance_deductions', 'yea_spouse_deduction', 'yea_specific_relative_deduction', 'yea_dependant_deduction', 'yea_personal_deductions'].map((key) => Number(get(elections, key, 0))));
// The balance keeps each scheme apart, so resident tax never counts as income tax withheld.
const withheld = paid('INCOME_TAX') + paid('YEAR_END_ADJUSTMENT') + Number(get(elections, 'prior_employer_tax', 0));
const taxable = round(income - social - declared - basic.offset, 1000, 'DOWN');
const tax = pick(ctx.lookup.annual_tax, taxable);
const adjusted = taxable <= 0 ? 0 : Math.max(0, taxable * tax.rate + tax.offset - Number(get(elections, 'yea_housing_loan_credit', 0)));
const difference = round(adjusted * ctx.lookup.reconstruction_multiplier, 100, 'DOWN') - withheld;
return difference;

RETIREMENT_TAX.employee_amount:
const pick = (rows, value) => {
	for (const row of rows) if (row.up_to == null || value <= row.up_to) return row;
	return rows[rows.length - 1];
};
const allowance = get(ctx.subtotals, 'RETIREMENT', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0);
// 所得税法 art.212: a non-resident's retirement pay is taxed flat.
if (get(ctx.subject.employment.terms, 'residency_status', '') === 'NON_RESIDENT') return round(allowance * ctx.lookup.nonresident_rate, 1, 'DOWN');
// 所得税法 art.201(3): without the 退職所得の受給に関する申告書 the payment is taxed flat, with no deduction.
const undeclared = get(ctx.subtotals, 'RETIREMENT_UNDECLARED', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0);
const flat = round(undeclared * ctx.lookup.no_declaration_rate, 1, 'DOWN');
const start = get(ctx.subject.employment, 'service_started_on', get(ctx.subject.employment, 'effective_range.from', ctx.run.salary_coverage.from));
// 所得税法施行令 art.69: service runs to the retirement day and a part year counts as a whole year.
const after = add_days(get(ctx.subject.employment, 'effective_range.to', ctx.run.pay_date), 1);
const months = calendar_completed_months(start, after);
const years = divide_round(add_months(start, months) < after ? months + 1 : months, 12, 0, 'UP');
const deduction = years <= 20 ? Math.max(years * ctx.lookup.annual_service_deduction, ctx.lookup.minimum_service_deduction) : ctx.lookup.breakpoint_deduction + (years - 20) * ctx.lookup.extended_annual_service_deduction;
const remainder = allowance - undeclared - deduction;
if (remainder <= 0) return flat;
// 所得税法 art.30(2): five years of service or less: no half for an officer, and only the first 3,000,000 halved for others.
let income = remainder * ctx.lookup.taxable_share;
if (years <= 5 && get(ctx.subject.employment.terms, 'work_classification', '') === 'OFFICER') income = remainder;
else if (years <= 5 && remainder > 3000000) income = remainder - 1500000;
const taxable = round(income, 1000, 'DOWN');
const band = pick(ctx.lookup.annual_tax, taxable);
return flat + round((taxable * band.rate + band.offset) * ctx.lookup.reconstruction_multiplier, 1, 'DOWN');

RESIDENT_TAX_RETIREMENT.employee_amount:
const allowance = get(ctx.subtotals, 'RETIREMENT', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0);
const start = get(ctx.subject.employment, 'service_started_on', get(ctx.subject.employment, 'effective_range.from', ctx.run.salary_coverage.from));
// 所得税法施行令 art.69: service runs to the retirement day and a part year counts as a whole year.
const after = add_days(get(ctx.subject.employment, 'effective_range.to', ctx.run.pay_date), 1);
const months = calendar_completed_months(start, after);
const years = divide_round(add_months(start, months) < after ? months + 1 : months, 12, 0, 'UP');
const deduction = years <= 20 ? Math.max(years * ctx.lookup.annual_service_deduction, ctx.lookup.minimum_service_deduction) : ctx.lookup.breakpoint_deduction + (years - 20) * ctx.lookup.extended_annual_service_deduction;
const remainder = allowance - deduction;
if (remainder <= 0) return 0;
if (get(ctx.subject.employment.employee_extension_data, 'statutory.RESIDENT_TAX_RETIREMENT.not_domiciled_on_january_1', false) === true) return 0;
// 所得税法 art.30(2): five years of service or less: no half for an officer, and only the first 3,000,000 halved for others.
let income = remainder * ctx.lookup.taxable_share;
if (years <= 5 && get(ctx.subject.employment.terms, 'work_classification', '') === 'OFFICER') income = remainder;
else if (years <= 5 && remainder > 3000000) income = remainder - 1500000;
const taxable = round(income, 1000, 'DOWN');
// Each tax is truncated to 100 yen on its own.
return round(taxable * ctx.lookup.municipal_rate, 100, 'DOWN') + round(taxable * ctx.lookup.prefectural_rate, 100, 'DOWN');

RESIDENT_TAX.eligibility:
// 地方税法 art.321の5: one instalment a month, deducted with the salary.
if (get(ctx.run, 'kind', '') === 'OFF_CYCLE') return false;
const monthly = Number(get(ctx.subject.employment.employee_extension_data, 'statutory.RESIDENT_TAX.monthly_amount', 0));
return monthly > 0 && get(ctx.subtotals, 'ORDINARY_WAGES', 0) > 0;

RESIDENT_TAX.employee_amount:
const elections = get(ctx.subject.employment.employee_extension_data, 'statutory.RESIDENT_TAX', {});
const monthly = Number(get(elections, 'monthly_amount', 0));
if (monthly <= 0) return 0;
const month = Number(ctx.run.salary_coverage.from.substring(5, 7));
const current = month === 6 ? Number(get(elections, 'june_amount', monthly)) : monthly;
const exitDate = get(ctx.subject.employment, 'effective_range.to', null);
const leaver = exitDate != null && exitDate >= ctx.run.salary_coverage.from && exitDate <= ctx.run.salary_coverage.to;
if (leaver !== true) return current;
const remaining = month <= 5 ? 5 - month : 17 - month;
if (get(elections, 'lump_sum_on_exit', false) === true) return current + monthly * remaining;
// 地方税法 art.321の5(2): from January to April the rest falls due unasked, where the pay covers it.
if (month > 4 || get(ctx.subtotals, 'ORDINARY_WAGES', 0) <= monthly * remaining) return current;
return current + monthly * remaining;

