ANNUAL_LEAVE_ATTENDANCE_REVIEW.effects:
// 労働基準法 art.39(1)–(2): each grant day closes the six months or the year whose attendance it turns on.
const contracts = ctx.reads.employee_contract;
const contract = contracts.find((row) => row.id === ctx.entry.employment_id);
const leave = first(ctx.reads.leave_catalog);
if (contract == null || leave == null) return [];
const started = get(contract, 'service_started_on', contract.effective_range.from);
const month = (date) => Number(date.substring(0, 4)) * 12 + Number(date.substring(5, 7));
const served = month(ctx.entry.period + '-01') - month(started);
const offset = leave.lookup.service_offset_months;
if (served < offset || (served - offset) % 12 !== 0) return [];
const grant = add_months(started, served);
const events = get(ctx.subject.employment, 'events', []);
if (events.some((event) => event.kind === 'ATTENDANCE_BELOW_RATIO' && event.on === grant)) return [];
const scheduled = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
const week = Number(get(ctx.subject.employment, 'terms.normal_days_per_week', 7 - scheduled.length));
const off = week === 7 - scheduled.length ? scheduled : [0, 6, 5, 4, 3, 2, 1].slice(0, 7 - week);
const shifts = group_by(ctx.reads.shift_definition, 'id');
const roster = Object.fromEntries(ctx.reads.roster_entry.map((row) => [row.work_date, get(first(get(shifts, String(row.shift_definition_id), [])) ?? {}, 'variant.day_type', 'WORK')]));
const holidays = ctx.reads.holiday.map((row) => row.date);
// art.39(10): leave the reads leave out counts as attended.
const own = ctx.reads.leave_catalog_entry.filter((entry) => contracts.some((row) => row.id === entry.employment_id));
const standing = own.map((entry) => entry.id);
const absences = group_by(ctx.reads.leave_catalog_entry_day.filter((day) => standing.includes(day.leave_entry_id)), 'incurred_on');
const from = served === offset ? started : add_months(grant, -12);
let working = 0;
let absent = 0;
for (let step = 0; step < calendar_distance_days(from, grant); step += 1) {
	const date = add_days(from, step);
	const type = get(roster, date, null);
	if (type == null ? off.includes(weekday(date)) || holidays.includes(date) : type !== 'WORK' && type !== 'ABS') continue;
	working += 1;
	absent += type === 'ABS' ? 1 : Math.min(1, get(absences, date, []).length / 2);
}
if (working - absent >= leave.lookup.attendance_ratio * working) return [];
return [{
	entity_id: ctx.entry.entity_id,
	employee_id: ctx.entry.employee_id,
	employment_id: ctx.entry.employment_id,
	title: ctx.lookup.message + ' ' + (working - absent) + '/' + working + ' days recorded.',
	due_on: grant,
	occurrence_key: occurrence_key(['JP', 'ANNUAL_LEAVE_ATTENDANCE_REVIEW', ctx.entry.employee_id, ctx.entry.period])
}];

