OVERTIME_MONTHLY_45H.condition:
if (ctx.reads.obligation.length > 0) return false;
const terms = ctx.subject.employment.terms;
if (['MANAGERIAL', 'OFFICER'].includes(get(terms, 'work_classification', 'ORDINARY'))) return false;
const shifts = ctx.reads.shift_definition;
const onRest = (row) => get(shifts.find((shift) => shift.id === row.shift_definition_id) ?? {}, 'variant.day_type', 'WORK') === 'REST';
const taken = (row) => (get(row, 'actual_worked_intervals', []).length > 0 ? interval_minutes(get(row, 'planned_overtime_intervals', [])) / 60 : 0);
const hours = ctx.reads.roster_entry.map((row) => ({ date: row.work_date, month: row.work_date.substring(0, 7), rest: onRest(row), taken: taken(row) })).filter((row) => row.taken > 0);
const overtime = group_sum(hours.filter((row) => !row.rest), 'month', 'taken');
const month = ctx.entry.period;
const inMonth = (table) => Number(get(table, month, 0));
const employer = get(ctx.subject.employer, 'entity_extension_data', {});
const end = month_end(month + '-01');
const from = get(employer, 'overtime_agreement_from', null);
const start = from == null || from > end ? month.substring(0, 4) + '-01-01' : add_months(from, Math.floor(calendar_completed_months(from, end) / 12) * 12);
const months = Object.entries(overtime).filter((pair) => pair[0] >= start.substring(0, 7) && pair[0] <= month);
if (!(inMonth(overtime) > ctx.lookup.monthly_overtime_hours_threshold)) return false;
if (get(employer, 'overtime_special_clause', false) !== true) return true;
return months.filter((pair) => pair[1] > ctx.lookup.monthly_overtime_hours_threshold).length > ctx.lookup.maximum_months_over_limit;

