lookup.entitlement:
// 労働基準法 art.39(1)–(2): a grant day six months after hire and each year after it, the days by length of service.
const employment = ctx.subject.employment;
const started = get(employment, 'service_started_on', get(employment, 'effective_range.from', null));
const offset = ctx.lookup.service_offset_months;
const months = calendar_completed_months(started, ctx.as_of);
if (months < offset) return 0;
const years = Math.floor((months - offset) / 12);
const grant = add_months(started, offset + years * 12);
// art.39(1)–(2): attendance below the ratio before a grant day leaves that year without a grant; HR records it on the day.
if (get(employment, 'events', []).some((event) => event.kind === 'ATTENDANCE_BELOW_RATIO' && event.on === grant)) return 0;
// art.39(3) with 施行規則 art.24の3: below the weekly hours and days, the table for the days scheduled.
const terms = get(employment, 'terms', {});
const hours = Number(get(terms, 'normal_hours_per_week', 0));
const perWeek = Number(get(terms, 'normal_days_per_week', ctx.lookup.full_time_days_per_week));
const full = perWeek >= ctx.lookup.full_time_days_per_week;
if (hours > 0 && hours < ctx.lookup.full_time_weekly_hours && !full) {
	const row = ctx.lookup.grant_days_by_normal_days_per_week.filter((item) => item.normal_days_per_week === perWeek && item.service_year <= years + 1).at(-1);
	return get(row ?? {}, 'days', 0);
}
return ctx.lookup.service_bands.filter((band) => band.service_months <= months).reduce((days, band) => Math.max(days, band.days), 0);

// 育児・介護休業法 art.16の2(1): days a business year by the children in third year of elementary school or below; 学校教育法 art.17(1): that is a child not yet the limiting age on the 1 April the school year opens.
const month = Number(ctx.as_of.substring(5, 7));
const opens = add_months(month_start(ctx.as_of), -((month + 12 - ctx.lookup.fiscal_year_start_month) % 12));
const children = get(ctx.subject.employment, 'events', []).filter((event) => event.kind === 'CHILD_BIRTH' && event.on <= ctx.as_of && get(event, 'ended_on', ctx.as_of) >= ctx.as_of && age_on(event.on, opens) < ctx.lookup.school_age_limit_years);
return children.length === 0 ? 0 : children.length === 1 ? ctx.lookup.days_one_child : ctx.lookup.days_two_or_more;

// 育児・介護休業法 art.16の5(1): days a business year by the family members in need of care the worker looks after.
const recipients = Number(get(ctx.subject.employment, 'employee_extension_data.family_care_recipients', 0));
return recipients === 0 ? 0 : recipients >= ctx.lookup.recipient_threshold ? ctx.lookup.days_two_or_more : ctx.lookup.days_one_recipient;

CHILD_SUPPORT_BONUS.eligibility:
const category = get(ctx.subject.employment.terms, 'statutory_work_category', 'NONE');
const facts = ctx.subject.employment.employee_extension_data;
// 高齢者医療確保法 arts.50, 52: cover ends on the 75th birthday itself, not its eve (the pension and care ages).
const age = age_on(get(ctx.subject.employment, 'payroll.date_of_birth', ''), ctx.run.salary_coverage.to);
if (!['SOCIAL_AND_EMPLOYMENT', 'SOCIAL_ONLY'].includes(category)) return false;
if (get(facts, 'statutory.HEALTH.social_security_agreement_exempt', false) === true) return false;
if (!(age < ctx.lookup.health_maximum_age_years)) return false;
const end = get(ctx.subject.employment, 'effective_range.to', null);
// 健康保険法 art.156(3), 厚生年金保険法 art.19(1): cover is lost the day after the exit, and that month is not charged.
if (end != null && !(end >= ctx.run.salary_coverage.to)) return false;
if (get(ctx.subject.employment.employee_extension_data, 'statutory.HEALTH.bonus_as_remuneration', false) === true) return false;
return get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0) !== 0;

CHILD_SUPPORT_BONUS.employee_amount:
const month = get(ctx.balances, 'month', {});
const heldIn = (paid, code) => (Object.hasOwn(month, paid + '.' + code) ? Number(month[paid + '.' + code]) : 0);
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
// 健康保険法 art.45: the ceiling runs April to March, on each month's bonus to the thousand.
const paidIn = Number(paidMonth.slice(5, 7));
const april = String(Number(paidMonth.slice(0, 4)) - (paidIn < 4 ? 1 : 0)) + '-04';
let prior = 0;
for (let paid = april; paid < paidMonth; paid = add_months(paid + '-01', 1).slice(0, 7)) {
	prior += round(heldIn(paid, 'ADDITIONAL_WAGES') - heldIn(paid, 'ORDINARY_WAGES'), 1000, 'DOWN');
}
const remaining = Math.max(0, ctx.lookup.annual_bonus_salary_ceiling - prior);
const levy = get(ctx.subject.employer.entity_extension_data, 'health_insurer', 'KYOKAI') === 'SOCIETY' ? Number(get(ctx.subject.employer.entity_extension_data, 'society_support_levy_rate_percent', ctx.lookup.support_rate * 100)) / 100 : ctx.lookup.support_rate;
// 健康保険法 art.45: every bonus paid in the month together, to the thousand.
const earlier = heldIn(paidMonth, 'ADDITIONAL_WAGES') - heldIn(paidMonth, 'ORDINARY_WAGES');
const now = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
// The employee share: 50 sen or less is dropped, above 50 sen rounds up (通貨の単位及び貨幣の発行等に関する法律 art.3).
const owed = (bonus) => round(Math.min(round(bonus, 1000, 'DOWN'), remaining) * levy * ctx.lookup.employee_share - 0.0001, 1, 'HALF_UP');
return owed(earlier + now) - owed(earlier);

CHILD_SUPPORT_BONUS.employer_amount:
const month = get(ctx.balances, 'month', {});
const heldIn = (paid, code) => (Object.hasOwn(month, paid + '.' + code) ? Number(month[paid + '.' + code]) : 0);
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
// 健康保険法 art.45: the ceiling runs April to March, on each month's bonus to the thousand.
const paidIn = Number(paidMonth.slice(5, 7));
const april = String(Number(paidMonth.slice(0, 4)) - (paidIn < 4 ? 1 : 0)) + '-04';
let prior = 0;
for (let paid = april; paid < paidMonth; paid = add_months(paid + '-01', 1).slice(0, 7)) {
	prior += round(heldIn(paid, 'ADDITIONAL_WAGES') - heldIn(paid, 'ORDINARY_WAGES'), 1000, 'DOWN');
}
const remaining = Math.max(0, ctx.lookup.annual_bonus_salary_ceiling - prior);
const levy = get(ctx.subject.employer.entity_extension_data, 'health_insurer', 'KYOKAI') === 'SOCIETY' ? Number(get(ctx.subject.employer.entity_extension_data, 'society_support_levy_rate_percent', ctx.lookup.support_rate * 100)) / 100 : ctx.lookup.support_rate;
// 健康保険法 art.45: every bonus paid in the month together, to the thousand.
const earlier = heldIn(paidMonth, 'ADDITIONAL_WAGES') - heldIn(paidMonth, 'ORDINARY_WAGES');
const now = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
const owed = (bonus) => {
	const total = Math.min(round(bonus, 1000, 'DOWN'), remaining) * levy;
	return round(total, 1, 'DOWN') - round(total * ctx.lookup.employee_share - 0.0001, 1, 'HALF_UP');
};
return Math.max(0, owed(earlier + now) - owed(earlier));

CHILD_SUPPORT.eligibility:
// The monthly premium goes with the salary: an off-cycle run pays none, and the bonus rows carry what it pays.
if (get(ctx.run, 'kind', '') === 'OFF_CYCLE') return false;
const category = get(ctx.subject.employment.terms, 'statutory_work_category', 'NONE');
const facts = ctx.subject.employment.employee_extension_data;
// 高齢者医療確保法 arts.50, 52: cover ends on the 75th birthday itself, not its eve (the pension and care ages).
const age = age_on(get(ctx.subject.employment, 'payroll.date_of_birth', ''), ctx.run.salary_coverage.to);
if (!['SOCIAL_AND_EMPLOYMENT', 'SOCIAL_ONLY'].includes(category)) return false;
if (get(facts, 'statutory.HEALTH.social_security_agreement_exempt', false) === true) return false;
if (!(age < ctx.lookup.health_maximum_age_years)) return false;
const end = get(ctx.subject.employment, 'effective_range.to', null);
// 健康保険法 art.156(3), 厚生年金保険法 art.19(1): cover is lost the day after the exit, and that month is not charged.
return end == null || end >= ctx.run.salary_coverage.to;

CHILD_SUPPORT.employee_amount:
const facts = ctx.subject.employment.employee_extension_data;
const elected = get(facts, 'statutory.HEALTH.standard_monthly_remuneration', null);
const grade = elected !== null ? Number(elected) : bracket(round(get(ctx.subtotals, 'ORDINARY_WAGES', 0), 1000, 'DOWN'), ctx.lookup.remuneration_grades);
const base = clamp(grade, ctx.lookup.health_minimum_grade, ctx.lookup.health_maximum_grade);
const levy = get(ctx.subject.employer.entity_extension_data, 'health_insurer', 'KYOKAI') === 'SOCIETY' ? Number(get(ctx.subject.employer.entity_extension_data, 'society_support_levy_rate_percent', ctx.lookup.support_rate * 100)) / 100 : ctx.lookup.support_rate;
const total = base * levy * Number(get(facts, 'statutory.HEALTH.apportionment_ratio', 1));
// The employee share: 50 sen or less is dropped, above 50 sen rounds up (通貨の単位及び貨幣の発行等に関する法律 art.3).
return round(total * ctx.lookup.employee_share - 0.0001, 1, 'HALF_UP');

CHILD_SUPPORT.employer_amount:
const facts = ctx.subject.employment.employee_extension_data;
const elected = get(facts, 'statutory.HEALTH.standard_monthly_remuneration', null);
const grade = elected !== null ? Number(elected) : bracket(round(get(ctx.subtotals, 'ORDINARY_WAGES', 0), 1000, 'DOWN'), ctx.lookup.remuneration_grades);
const base = clamp(grade, ctx.lookup.health_minimum_grade, ctx.lookup.health_maximum_grade);
const levy = get(ctx.subject.employer.entity_extension_data, 'health_insurer', 'KYOKAI') === 'SOCIETY' ? Number(get(ctx.subject.employer.entity_extension_data, 'society_support_levy_rate_percent', ctx.lookup.support_rate * 100)) / 100 : ctx.lookup.support_rate;
const total = base * levy * Number(get(facts, 'statutory.HEALTH.apportionment_ratio', 1));
return round(total, 1, 'DOWN') - round(total * ctx.lookup.employee_share - 0.0001, 1, 'HALF_UP');

SHORT_TIME_COVERAGE.condition:
if (ctx.reads.obligation.length > 0) return false;
const terms = ctx.subject.employment.terms;
const hours = Number(get(terms, 'normal_hours_per_week', 0));
if (hours < ctx.lookup.minimum_weekly_hours) return false;
if (hours >= ctx.lookup.standard_coverage_weekly_hours) return false;
const covered = ['SOCIAL_AND_EMPLOYMENT', 'SOCIAL_ONLY'].includes(get(terms, 'statutory_work_category', 'NONE'));
const student = get(ctx.subject.employment.employee_extension_data, 'daytime_student', false) === true;
// 令和7年法律第74号: from 1 October 2026 the 88,000 test binds only a worker under a minimum-wage reduction permit (特定減額特例対象者).
const reduced = Number(get(ctx.subject.employment.employee_extension_data, 'minimum_wage_reduction_rate', 0)) > 0;
const wage = !reduced || Number(get(ctx.entry, 'basic_earnings', 0)) >= ctx.lookup.minimum_monthly_wage;
// The pension office's notice or an approved voluntary application makes the employer a covered one, not its raw headcount.
const filed = ctx.reads.workplace_case_catalog_entry.some((c) => ctx.lookup.employer_case_kinds.includes(c.kind) && get(c, 'closed_on', null) == null);
const establishment = ctx.lookup.employer_headcount_threshold == null || filed;
return covered !== (!student && wage && establishment);

HARASSMENT_PREVENTION_2026_AMENDMENT.condition:
if (ctx.entry.status !== 'SEALED') return false;
if (ctx.reads.obligation.length > 0) return false;
const end = get(ctx.entry, 'effective_range.to', null);
return end == null || end >= ctx.lookup.effective_date;

HARASSMENT_PREVENTION_2026_AMENDMENT.effects:
const due = ctx.lookup.effective_date;
return [{
	entity_id: ctx.entry.entity_id,
	title: "カスタマーハラスメント・求職者等セクシュアルハラスメント防止措置 (customer and job-seeker harassment measures, October 2026)",
	due_on: due,
	occurrence_key: occurrence_key(['JP', 'HARASSMENT_PREVENTION_2026_AMENDMENT', ctx.entry.entity_id, '2026-10-01'])
}];
